        lines = []
        for row in reader:
            vals = []
            for val in row:
                if val == '':
                    vals.append('NULL')
                else:
                    escaped = val.replace(\"'\", \"''\")
                    vals.append(f\"'{escaped}'\")
            lines.append(f\"INSERT INTO {table_name} VALUES ({', '.join(vals)});\");
        return lines

